import sqlite3

RAW = [(1, 1250, 'paid'), (2, 300, 'failed'), (3, 725, 'refunded')]

def load(conn, rows):
    conn.execute('CREATE TABLE IF NOT EXISTS orders_clean (order_id INTEGER PRIMARY KEY, amount_cents INTEGER, status TEXT)')
    with conn:
        for oid, amount, status in rows:
            if status != 'failed':
                conn.execute('INSERT OR REPLACE INTO orders_clean VALUES (?, ?, ?)', (oid, amount, status))

def summary(conn):
    return conn.execute('SELECT COUNT(*), SUM(amount_cents) FROM orders_clean').fetchone()

def test_rerun_idempotent():
    conn = sqlite3.connect(':memory:')
    load(conn, RAW)
    load(conn, RAW)
    assert summary(conn) == (2, 1975)

def test_changed_amount_updates():
    conn = sqlite3.connect(':memory:')
    load(conn, RAW)
    load(conn, [(1, 2000, 'paid')] + RAW[1:])
    assert summary(conn) == (2, 2725)

test_rerun_idempotent()
test_changed_amount_updates()
print('done')

