import pytest
from transforms import dedupe_latest

@pytest.fixture
def rows():
    return [
        {"order_id": 3, "updated_at": "2026-01-01", "status": "paid"},
        {"order_id": 1, "updated_at": "2026-01-01", "status": "paid"},
        {"order_id": 1, "updated_at": "2026-01-04", "status": "refunded"},
        {"order_id": 2, "updated_at": "2026-01-02", "status": "paid"},
        {"order_id": 2, "updated_at": "2026-01-02", "status": "paid"},
    ]

def test_one_row_per_key(rows):
    assert [r["order_id"] for r in dedupe_latest(rows)] == [1, 2, 3]

@pytest.mark.parametrize("order_id, status", [(1, "refunded"), (2, "paid"), (3, "paid")])
def test_latest_wins(rows, order_id, status):
    got = {r["order_id"]: r for r in dedupe_latest(rows)}
    assert got[order_id]["status"] == status

def test_empty():
    assert dedupe_latest([]) == []
```

The fixture contains an out-of-order key, a key with a newer update, and an exact duplicate, which are the shapes of real duplicate data. The parametrized test checks every key's surviving status, and the empty list guards the boundary where a loop-based implementation might fail.
